interface Produk {
  readonly kode: string;
  harga: number;
  diskon?: number;
}
const katalog: Produk[] = [
  { kode: "A", harga: 18000, diskon: 3000 },
  { kode: "B", harga: 12000 },
  { kode: "C", harga: 15000, diskon: 3000 },
];
const total = katalog.reduce((a, p) => a + p.harga - (p.diskon ?? 0), 0);
const adaDiskon = katalog.filter((p) => p.diskon !== undefined).length;
console.log("Total:", total);
console.log("Diskon:", adaDiskon, "produk");
